function normFacultyCourseName(name) {
  return String(name || '')
    .replace(/[۰-۹0-9]/g, '')
    .replace(/[يی]/g, 'ی')
    .replace(/[كک]/g, 'ک')
    .replace(/[\u200c\s]+/g, ' ')
    .trim();
}

/**
 * ساخت خودکار، پویا و استاندارد چارت برای هر دانشکده بر اساس یونیورسال مپ خواجه نصیر
 */
export function buildFacultyCurriculum(targetFaculty, degreeTitle) {
  const courses = [];
  const addedCodes = new Set();
  const addedNormNames = new Set();

  // ۱. تمام دروس متعلق به این دانشکده در دیتابیس خواجه نصیر
  for (const [code, info] of Object.entries(UNIVERSAL_PREREQ_MAP)) {
    if (info.faculty === targetFaculty && !addedCodes.has(code)) {
      const pName = toPersianCourseName(info.name);
      courses.push({
        code,
        name: pName,
        units: Number(info.units) || 3,
        category: info.type ? toPersianCourseName(info.type) : 'تخصصی الزامی',
        faculty: info.faculty,
        term: 1, // توسط الگوریتم عمق پیش‌نیاز در پایین محاسبه می‌شود
        prerequisites: (info.prereqs || []).map((p) => ({
          ...p,
          name: toPersianCourseName(p.name),
        })),
        corequisites: (info.coreqs || []).map((c) => ({
          ...c,
          name: toPersianCourseName(c.name),
        })),
        unlocks: [],
      });
      addedCodes.add(code);
      addedNormNames.add(normFacultyCourseName(pName));
    }
  }

  // ۲. دروس پایه و عمومی مصوب و مشترک دانشگاه خواجه نصیر
  const commonCodes = [
    '5712094', // ریاضی عمومی ۱
    '5712096', // ریاضی عمومی ۲
    '5712095', // معادلات دیفرانسیل
    '4210113', // فیزیک ۱
    '4210115', // فیزیک ۲
    '4210114', // آزمایشگاه فیزیک ۱
    '4210116', // آزمایشگاه فیزیک ۲
    '5512004', // فارسی
    '5505044', // زبان خارجه
    '5514128', // اندیشه اسلامی ۱
    '5514002', // اندیشه اسلامی ۲
    '5505023', // تربیت بدنی ۱
    '5505030', // تربیت بدنی ۲
    '5514015', // آیین زندگی
    '5514005', // تاریخ تحلیلی صدر اسلام
    '5514008', // انقلاب اسلامی ایران
    '5514010', // دانش خانواده و جمعیت
  ];

  for (const code of commonCodes) {
    if (!addedCodes.has(code) && UNIVERSAL_PREREQ_MAP[code]) {
      const info = UNIVERSAL_PREREQ_MAP[code];
      const pName = toPersianCourseName(info.name);
      const normN = normFacultyCourseName(pName);
      if (!addedNormNames.has(normN)) {
        courses.push({
          code,
          name: pName,
          units: Number(info.units) || 2,
          category: info.faculty?.includes('عمومی') ? 'دروس عمومی' : 'دروس پایه',
          faculty: info.faculty,
          term: 1,
          prerequisites: (info.prereqs || []).map((p) => ({
            ...p,
            name: toPersianCourseName(p.name),
          })),
          corequisites: (info.coreqs || []).map((c) => ({
            ...c,
            name: toPersianCourseName(c.name),
          })),
          unlocks: [],
        });
        addedCodes.add(code);
        addedNormNames.add(normN);
      }
    }
  }

  // توزیع هوشمند ترم‌ها بر پایهٔ عمق گراف پیش‌نیازها
  const courseCodeMap = new Map(courses.map((c) => [c.code, c]));
  function calcDepth(c, visited = new Set()) {
    if (visited.has(c.code)) return 1;
    visited.add(c.code);
    let d = 1;
    for (const p of c.prerequisites || []) {
      if (p.code && courseCodeMap.has(p.code)) {
        d = Math.max(d, 1 + calcDepth(courseCodeMap.get(p.code), new Set(visited)));
      }
    }
    return Math.min(8, d);
  }

  // توزیع استاندارد ترم‌ها برای دروس عمومی مشترک دانشگاه
  const generalTermMap = {
    '5512004': 1, // فارسی
    '5505044': 1, // زبان خارجه
    '5514128': 2, // اندیشه اسلامی ۱
    '5514001': 2, // معارف ۱
    '5505023': 2, // تربیت بدنی ۱
    '5514015': 3, // آیین زندگی
    '5514004': 3, // اخلاق اسلامی
    '5514002': 4, // اندیشه ۲
    '5505030': 4, // تربیت بدنی ۲
    '5514005': 5, // تاریخ اسلام
    '5505029': 5, // تاریخ اسلام
    '5514010': 6, // دانش خانواده
    '5514016': 6, // دانش خانواده
    '5505032': 7, // متون اسلامی
    '5514008': 8, // انقلاب اسلامی
    '5514003': 8, // انقلاب اسلامی
  };

  for (const c of courses) {
    if (generalTermMap[c.code]) {
      c.term = generalTermMap[c.code];
    } else {
      c.term = calcDepth(c);
    }
  }

  return {
    degreeTitle: toPersianCourseName(degreeTitle || `${targetFaculty} — کارشناسی پیوسته`),
    faculty: targetFaculty,
    university: 'دانشگاه صنعتی خواجه نصیرالدین طوسی',
    defaultRequiredCredits: 140,
    courses,
    categories: [
      { id: 'base', title: 'دروس پایه', minUnits: 20, color: 'primary' },
      { id: 'core', title: 'دروس تخصصی الزامی', minUnits: 65, color: 'accent' },
      { id: 'general', title: 'دروس عمومی', minUnits: 22, color: 'info' },
      { id: 'elective', title: 'دروس تخصصی انتخابی', minUnits: 20, color: 'secondary' },
      { id: 'extra', title: 'سایر دروس', minUnits: 0, color: 'neutral' },
    ],
  };
}

/**
 * تشخیص هوشمند، پویا و کاملاً یونیورسال چارت برای تمامی ۱۱ دانشکده دانشگاه خواجه نصیرالدین طوسی
 */
export function resolveCurriculumForMajor(majorNameOrFaculty = '', userCourses = []) {
  const s = String(majorNameOrFaculty || '').trim();

  // ۱. بررسی بر اساس نام رشته یا دانشکده در بهستان
  if (/مکانیک|مكانيك|mechanic/i.test(s)) {
    return buildFacultyCurriculum('مهندسي مكانيك', 'مهندسی مکانیک — کارشناسی پیوسته');
  }
  if (/عمران|civil/i.test(s)) {
    return buildFacultyCurriculum('مهندسي عمران', 'مهندسی عمران — کارشناسی پیوسته');
  }
  if (/برق|electrical/i.test(s)) {
    return buildFacultyCurriculum('مهندسي برق', 'مهندسی برق — کارشناسی پیوسته');
  }
  if (/هوافضا|aerospace/i.test(s)) {
    return buildFacultyCurriculum('مهندسي هوافضا', 'مهندسی هوافضا — کارشناسی پیوسته');
  }
  if (/نقشه|نقشه‌برداری|نقشه برداری|ژئوماتیک|geomatic/i.test(s)) {
    return buildFacultyCurriculum('مهندسي نقشه برداري', 'مهندسی نقشه‌برداری — کارشناسی پیوسته');
  }
  if (/مواد|متالورژی|materials/i.test(s)) {
    return buildFacultyCurriculum('مهندسي و علم مواد', 'مهندسی مواد و متالورژی — کارشناسی پیوسته');
  }
  if (/فیزیک|فيزيك|physics/i.test(s)) {
    return buildFacultyCurriculum('فيزيك', 'فیزیک — کارشناسی پیوسته');
  }
  if (/شیمی|شيمي|chemistry/i.test(s)) {
    return buildFacultyCurriculum('شيمي', 'شیمی — کارشناسی پیوسته');
  }
  if (/ریاضی|رياضي|mathematics|math/i.test(s)) {
    return buildFacultyCurriculum('رياضي', 'ریاضیات و کاربردها — کارشناسی پیوسته');
  }
  if (/کامپیوتر|كامپيوتر|نرم\s*افزار|سخت\s*افزار|it|فناوری|computer/i.test(s)) {
    return KNTU_CE_CURRICULUM;
  }
  if (/صنایع|صنايع|industrial/i.test(s)) {
    return KNTU_IE_CURRICULUM;
  }

  // ۲. بررسی بر اساس کدهای دروس کارنامه دانشجو (پیش‌شماره‌های دپارتمان‌ها)
  if (Array.isArray(userCourses) && userCourses.length > 0) {
    if (userCourses.some((c) => String(c?.code || '').startsWith('333') || String(c?.code || '').startsWith('339') || String(c?.code || '').startsWith('336'))) {
      return buildFacultyCurriculum('مهندسي مكانيك', 'مهندسی مکانیک — کارشناسی پیوسته');
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('222') || String(c?.code || '').startsWith('227'))) {
      return buildFacultyCurriculum('مهندسي عمران', 'مهندسی عمران — کارشناسی پیوسته');
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('111') || String(c?.code || '').startsWith('112'))) {
      return buildFacultyCurriculum('مهندسي برق', 'مهندسی برق — کارشناسی پیوسته');
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('888') || String(c?.code || '').startsWith('889'))) {
      return buildFacultyCurriculum('مهندسي هوافضا', 'مهندسی هوافضا — کارشناسی پیوسته');
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('770') || String(c?.code || '').startsWith('772') || String(c?.code || '').startsWith('777'))) {
      return buildFacultyCurriculum('مهندسي نقشه برداري', 'مهندسی نقشه‌برداری — کارشناسی پیوسته');
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('991') || String(c?.code || '').startsWith('992'))) {
      return buildFacultyCurriculum('مهندسي و علم مواد', 'مهندسی مواد و متالورژی — کارشناسی پیوسته');
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('421'))) {
      return buildFacultyCurriculum('فيزيك', 'فیزیک — کارشناسی پیوسته');
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('481') || String(c?.code || '').startsWith('482'))) {
      return buildFacultyCurriculum('شيمي', 'شیمی — کارشناسی پیوسته');
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('570') || String(c?.code || '').startsWith('571'))) {
      return buildFacultyCurriculum('رياضي', 'ریاضیات و کاربردها — کارشناسی پیوسته');
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('191') || String(c?.code || '').startsWith('192'))) {
      return KNTU_CE_CURRICULUM;
    }
    if (userCourses.some((c) => String(c?.code || '').startsWith('666') || String(c?.code || '').startsWith('668'))) {
      return KNTU_IE_CURRICULUM;
    }

    // ۳. یافتن دانشکده‌ای که بیشترین دروس اختصاصی را در سوابق دانشجو دارد
    const facultyCounts = {};
    for (const c of userCourses) {
      const code = String(c?.code || '').trim();
      const info = UNIVERSAL_PREREQ_MAP[code];
      if (info?.faculty && !info.faculty.includes('عمومی') && !info.faculty.includes('الکترونیکی')) {
        facultyCounts[info.faculty] = (facultyCounts[info.faculty] || 0) + 1;
      }
    }
    const sortedFaculties = Object.entries(facultyCounts).sort((a, b) => b[1] - a[1]);
    if (sortedFaculties.length > 0 && sortedFaculties[0][1] > 0) {
      const bestFaculty = sortedFaculties[0][0];
      return buildFacultyCurriculum(bestFaculty, `${bestFaculty} — کارشناسی پیوسته`);
    }
  }

  // چارت پیش‌فرض
  return KNTU_IE_CURRICULUM;
}
